USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_WorkOrder_CreateAndAssign @WorkOrderNo VARCHAR(60),@WorkOrderDate DATE,@SupplierVendor NVARCHAR(300),@ContractAgreementNo VARCHAR(100)=NULL,@WorkOrderValue DECIMAL(18,2),@DeliveryDate DATE=NULL,@Remarks NVARCHAR(2000)=NULL,@Requisitions dbo.WorkOrderRequisitionTableType READONLY,@ActorEmployeeId VARCHAR(30)
AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRY BEGIN TRAN; IF NOT EXISTS(SELECT 1 FROM @Requisitions) THROW 51000,'At least one requisition is required.',1; IF EXISTS(SELECT 1 FROM @Requisitions x LEFT JOIN dbo.PROCUREMENT_TRACKING p ON p.REQUISITION_ID=x.REQUISITION_ID WHERE p.PROCUREMENT_ID IS NULL) THROW 51000,'All requisitions must be ready for procurement.',1; INSERT dbo.WORK_ORDER_HEADER(WORK_ORDER_NO,WORK_ORDER_DATE,SUPPLIER_VENDOR,CONTRACT_AGREEMENT_NO,WORK_ORDER_VALUE,DELIVERY_DATE,REMARKS,CREATED_BY) VALUES(@WorkOrderNo,@WorkOrderDate,@SupplierVendor,@ContractAgreementNo,@WorkOrderValue,@DeliveryDate,@Remarks,@ActorEmployeeId); DECLARE @id BIGINT=SCOPE_IDENTITY(); INSERT dbo.WORK_ORDER_REQUISITION(WORK_ORDER_ID,REQUISITION_ID,ALLOCATED_AMOUNT,REMARKS) SELECT @id,REQUISITION_ID,ALLOCATED_AMOUNT,REMARKS FROM @Requisitions; DECLARE @sid BIGINT=(SELECT STATUS_ID FROM dbo.PROCUREMENT_STATUS_MASTER WHERE STATUS_CODE='WORK_ORDER_ISSUED' AND IS_ACTIVE=1); UPDATE p SET CURRENT_STATUS_ID=@sid,MODIFIED_DATE=SYSUTCDATETIME(),PROCUREMENT_REFERENCE_NO=COALESCE(p.PROCUREMENT_REFERENCE_NO,@WorkOrderNo) FROM dbo.PROCUREMENT_TRACKING p JOIN @Requisitions x ON x.REQUISITION_ID=p.REQUISITION_ID; INSERT dbo.PROCUREMENT_STATUS_HISTORY(PROCUREMENT_ID,STATUS_ID,REFERENCE_NO,CHANGED_BY_EMPLOYEE_ID,REMARKS) SELECT p.PROCUREMENT_ID,@sid,@WorkOrderNo,@ActorEmployeeId,@Remarks FROM dbo.PROCUREMENT_TRACKING p JOIN @Requisitions x ON x.REQUISITION_ID=p.REQUISITION_ID; COMMIT; SELECT '000' RESULT_CODE,N'Success' RESULT_MESSAGE,@id ENTITY_ID,@WorkOrderNo REFERENCE_NO; END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK; SELECT CASE WHEN ERROR_NUMBER()=51000 THEN '001' WHEN ERROR_NUMBER() IN(2601,2627) THEN '005' ELSE '999' END RESULT_CODE,ERROR_MESSAGE() RESULT_MESSAGE,NULL ENTITY_ID,@WorkOrderNo REFERENCE_NO; END CATCH END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_WorkOrder_GetByRequisition @RequisitionId BIGINT AS BEGIN SET NOCOUNT ON; SELECT w.*,x.ALLOCATED_AMOUNT,x.REMARKS ASSIGNMENT_REMARKS FROM dbo.WORK_ORDER_REQUISITION x JOIN dbo.WORK_ORDER_HEADER w ON w.WORK_ORDER_ID=x.WORK_ORDER_ID WHERE x.REQUISITION_ID=@RequisitionId ORDER BY w.WORK_ORDER_DATE DESC; END;
GO

